RANK_UNIVERSE_SHA256 = "357270acc06e5bc83b7ce399182ae77f5923550fa620f20095ef86c082f7a5a9"
EXPECTED_PREVIOUS_VERSION = "METABRIC_HARMONIZED_SIGNATURE_REPRODUCTION_V1"
EXPECTED_PROGRAMME_GMT_SHA256 = "1f0899908ff29b2a84ae090991ea6a6e5f82b27e13cf8b7600fa4ec0aa23c77a"
DISCOVERY_MAX_DEPTH = 6
DISCOVERY_MAX_DIRECTORIES = 4096
DISCOVERY_MAX_ENTRIES = 100000
DISCOVERY_MAX_MANIFEST_BYTES = 2 * 1024 * 1024
DISCOVERY_SKIPPED_DIRECTORIES = frozenset({".git", ".venv", "venv", "env", "node_modules", "__pycache__", ".cache", ".tox", ".mypy_cache", ".pytest_cache"})

