def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(4 * 1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def text_sha256(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def gene_id(value: str) -> str:
    require(bool(re.fullmatch(r"[1-9][0-9]*", value)), "Noncanonical Entrez identifier: " + repr(value))
    return value


def gene_set_sha256(genes: set[str]) -> str:
    return text_sha256("".join(identifier + "\n" for identifier in sorted(genes, key=int)))


def read_json(path: Path) -> dict:
    require(path.is_file() and not path.is_symlink(), "Missing or symbolic input: " + str(path))
    return json.loads(path.read_text(encoding="utf-8"))


def write_json(path: Path, value: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")
    os.replace(temporary, path)


def read_csv(path: Path, expected_sha256: str | None = None) -> list[dict[str, str]]:
    require(path.is_file() and not path.is_symlink(), "Missing or symbolic input: " + str(path))
    if expected_sha256 is not None:
        require(file_sha256(path) == expected_sha256, "Input definition hash differs: " + path.name)
    with path.open(encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def write_csv(path: Path, rows, fields: list[str]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def write_compressed_csv(path: Path, rows, fields: list[str]) -> None:
    with path.open("wb") as raw:
        with gzip.GzipFile(filename="", fileobj=raw, mode="wb", mtime=0, compresslevel=6) as compressed:
            with io.TextIOWrapper(compressed, encoding="utf-8", newline="") as handle:
                writer = csv.DictWriter(handle, fieldnames=fields, lineterminator="\n")
                writer.writeheader()
                writer.writerows(rows)


def parse_boolean(value: str, label: str) -> bool:
    require(value in {"True", "False"}, "Invalid Boolean in reviewed definitions: " + label)
    return value == "True"


def parse_optional_integer(value: str, label: str) -> int | None:
    require(value == "" or re.fullmatch(r"[0-9]+", value), "Invalid nonnegative count: " + label)
    return int(value) if value else None


def verify_embedded_definitions() -> None:
    for name, text in (("group_metadata", REVIEWED_GROUP_METADATA), ("group_memberships", REVIEWED_GROUP_MEMBERSHIPS), ("ranking_universe", REVIEWED_RANK_UNIVERSE), ("deferred_groups", DEFERRED_GROUPS)):
        require(text_sha256(text) == EMBEDDED_DEFINITION_SHA256[name], "Embedded reviewed definition changed: " + name)


def load_reviewed_groups(universe: set[str]) -> list[dict]:
    verify_embedded_definitions()
    records = list(csv.DictReader(io.StringIO(REVIEWED_GROUP_METADATA), delimiter="\t"))
    require(len(records) == EXPECTED_REVIEWED_GROUPS, "Reviewed group count changed")
    groups = {}
    integer_fields = {"published_source_rows", "accepted_source_rows", "source_rows_in_universe", "unresolved_source_rows", "resolved_outside_universe_rows", "programme_order", "effective_gene_count"}
    boolean_fields = {"published_list_enumeration_complete", "included_in_exploratory_programmes", "active_for_coverage", "new_score_authorized"}
    for raw in records:
        record = dict(raw)
        name = record["group_id"]
        require(name and name not in groups, "Missing or duplicate reviewed group identifier")
        for field in integer_fields:
            record[field] = parse_optional_integer(record[field], name + ":" + field)
        for field in boolean_fields:
            record[field] = parse_boolean(record[field], name + ":" + field)
        for field, default in SOURCE_REVIEW_DEFAULTS.items():
            record[field] = record[field] or default
        require(record["new_score_authorized"] is False, "Reviewed definition unexpectedly opens scoring")
        record["memberships"] = []
        record["gene_ids"] = set()
        groups[name] = record
    row_count = 0
    for row in csv.DictReader(io.StringIO(REVIEWED_GROUP_MEMBERSHIPS), delimiter="\t"):
        require(row["group_id"] in groups, "Membership references an unknown group")
        record = groups[row["group_id"]]
        genes = [gene_id(value) for value in row["gene_ids"].split(",") if value]
        require(genes and len(genes) == len(set(genes)), "Empty or duplicated reviewed membership segment")
        require(set(genes) <= universe, "Reviewed membership outside the unchanged ranking universe")
        record["memberships"].append({"arm": row["arm"], "mapping_status": row["mapping_status"], "gene_ids": genes})
        record["gene_ids"].update(genes)
        row_count += len(genes)
    require(row_count == EXPECTED_REVIEWED_MEMBERSHIPS, "Reviewed entity-arm-gene count changed")
    digest = hashlib.sha256()
    for name in sorted(groups):
        record = groups[name]
        require(len(record["gene_ids"]) == record["effective_gene_count"], "Effective membership count differs: " + name)
        keys = []
        for part in record["memberships"]:
            keys.extend((part["arm"], int(identifier), part["mapping_status"]) for identifier in part["gene_ids"])
        require(len(keys) == len({(arm, identifier) for arm, identifier, status in keys}), "Duplicate gene within the same group arm")
        for arm, identifier, status in sorted(keys):
            digest.update((name + "\t" + arm + "\t" + str(identifier) + "\t" + status + "\n").encode("utf-8"))
        if record["included_in_exploratory_programmes"]:
            require(15 <= len(record["gene_ids"]) <= 500, "Registered programme size constraint differs")
            require(record["unresolved_source_rows"] in {0, None}, "Unresolved identities entered the exploratory programme dictionary")
            require(record["programme_order"] is not None, "Missing programme order")
    require(digest.hexdigest() == REVIEWED_MEMBERSHIP_RELATION_SHA256, "Reviewed group/arm/gene/restriction relations changed")
    programmes = [record for record in records_as_list(groups) if record["included_in_exploratory_programmes"]]
    require(len(programmes) == EXPECTED_PROGRAMME_LABELS and {record["programme_order"] for record in programmes} == set(range(EXPECTED_PROGRAMME_LABELS)), "Registered programme labels or ordering changed")
    profiles = {gene_set_sha256(record["gene_ids"]) for record in programmes}
    require(len(profiles) == EXPECTED_PROGRAMME_PROFILES, "Exact programme-alias structure changed")
    coverage = set().union(*(record["gene_ids"] for record in groups.values() if record["active_for_coverage"]))
    require(len(coverage) == EXPECTED_COVERED_GENES, "Reviewed active gene coverage changed")
    require(sum(record["collection"] == "Hallmark" for record in groups.values()) == 50, "The 50 Hallmark groups changed")
    return records_as_list(groups)


def records_as_list(groups: dict[str, dict]) -> list[dict]:
    return list(groups.values())


def safe_input(root: Path, relative: str) -> Path:
    relative_path = Path(relative)
    require(not relative_path.is_absolute() and ".." not in relative_path.parts, "Unsafe previous-step input path")
    path = root / relative_path
    require(path.is_file() and not path.is_symlink(), "Previous-step input is missing or symbolic: " + str(path))
    return path


def read_previous_outputs(transcriptomics_dir: Path, signature_scores_dir: Path) -> dict:
    transcriptomics_dir = transcriptomics_dir.resolve(strict=True)
    signature_scores_dir = signature_scores_dir.resolve(strict=True)
    inspected = {}
    def track(path: Path) -> Path:
        inspected[str(path)] = file_sha256(path)
        return path
    completed_path = track(safe_input(signature_scores_dir, "RUN_STATE.json"))
    completed = read_json(completed_path)
    require(completed.get("status") == "COMPLETED_NOT_FROZEN", "Step04 did not finish successfully")
    manifest = read_json(track(safe_input(signature_scores_dir, "results/manifest_v1.json")))
    require(manifest.get("version") == EXPECTED_PREVIOUS_VERSION and manifest.get("status") == "PASS_VALIDATED_NOT_FROZEN", "Wrong or incomplete step04 output")
    require(manifest.get("outcome_files_read") == [] and manifest.get("clinical_files_read") == [] and manifest.get("models_fitted") is False and manifest.get("thresholds_selected") is False, "Step04 manifest differs from the expected transcriptomic-only contract")
    universe_path = track(safe_input(signature_scores_dir, "results/metabric_rank_universe_v1_entrez.txt"))
    require(inspected[str(universe_path)] == RANK_UNIVERSE_SHA256, "Step04 ranking-universe hash differs")
    universe = [gene_id(value) for value in universe_path.read_text(encoding="utf-8").splitlines()]
    require(len(universe) == len(set(universe)) == EXPECTED_RANK_GENES, "Step04 ranking universe differs")
    tables = {}
    for name, expected in EXPECTED_PREVIOUS_DEFINITION_SHA256.items():
        path = track(safe_input(signature_scores_dir, "definitions/" + name))
        tables[name] = read_csv(path, expected)
    annotation = read_csv(track(safe_input(transcriptomics_dir, "metabric_gene_annotation.csv")))
    canonical = [gene_id(row["Entrez_Gene_Id"]) for row in annotation]
    require(len(canonical) == len(set(canonical)) == EXPECTED_CANONICAL_GENES, "Step03 canonical gene annotation differs")
    require(set(canonical) == set(universe) | set(PREVIOUS_MISSING_GENE_COUNTS), "Step03 annotation and step04 gene exclusions are inconsistent")
    summary_rows = read_csv(track(safe_input(transcriptomics_dir, "metabric_transcriptomics_summary.csv")))
    summary = {row["metric"]: int(row["value"]) for row in summary_rows}
    require(summary.get("canonical_entrez_genes") == EXPECTED_CANONICAL_GENES and summary.get("selected_samples") == EXPECTED_CANONICAL_SAMPLES and summary.get("missing_expression_cells") == sum(PREVIOUS_MISSING_GENE_COUNTS.values()), "Step03 transcriptomic summary differs from the frozen gene/universe contract")
    require(len(tables["signature_readiness_v1.csv"]) == 18 and len(tables["repository_control_readiness_v1.csv"]) == 9, "Earlier signature/control inventory changed")
    membership = tables["membership_entrez_deduplicated_v1.csv"]
    require(len(membership) == 577, "Step04 mapped reference memberships changed")
    seen = set()
    universe_set = set(universe)
    for row in membership:
        identifier = gene_id(row["mapped_human_entrez_current"])
        key = (row["Membership entity ID"], identifier)
        require(key not in seen and row["in_metabric_rank_universe"] in {"YES", "NO"}, "Duplicated or malformed step04 reference membership")
        seen.add(key)
        require((identifier in universe_set) == (row["in_metabric_rank_universe"] == "YES"), "Step04 reference gene universe flag differs")
    specifications = tables["future_scoring_specifications_v1.csv"]
    allowed = {row["entity_id"] for row in specifications}
    require(len(allowed) == 10 and allowed == {"SIG_KIM49"} | {row["Membership entity ID"] for row in tables["repository_control_readiness_v1.csv"]}, "Earlier scoring definitions changed")
    require(allowed == set(manifest.get("authorized_score_entities", [])), "Step04 manifest and earlier scoring definitions disagree")
    require(all(row["paired_arm_combination_authorized"] == "NO" for row in tables["repository_control_readiness_v1.csv"]), "Control-arm combination permission changed")
    return {"universe": set(universe), "tables": tables, "existing_score_entities": allowed, "input_hashes": inspected, "previous_score_equivalence_declaration": manifest.get("canonical_score_equivalence", "NOT_REPORTED"), "earlier_patient_scores_rechecked": False, "earlier_clinical_models_rechecked": False, "upstream_evidence_is_synthetic_fixture": bool(completed.get("fixture_only", False) or manifest.get("fixture_only", False))}


def previous_reference_records(previous: dict) -> tuple[list[dict], list[dict]]:
    tables = previous["tables"]
    members = []
    by_group = defaultdict(list)
    for row in tables["membership_entrez_deduplicated_v1.csv"]:
        member = {"group_id": row["Membership entity ID"], "entrez_id": row["mapped_human_entrez_current"], "published_direction": row["Dirección/rol publicado"], "in_ranking_universe": row["in_metabric_rank_universe"] == "YES"}
        members.append(member)
        by_group[member["group_id"]].append(member)
    references = []
    for row in tables["signature_readiness_v1.csv"]:
        name = row["Signature ID"]
        references.append({"group_id": name, "name": row["Nombre"], "reference_type": "Literature signature", "readiness_status": row["readiness_status"], "primary_blocker": row["primary_blocker"], "published_direction_rule": row["direction_rule"], "existing_score_available": name in previous["existing_score_entities"], "outcome_supervised_derivation": row["outcome_supervised_derivation"], "source_metabric_outcome_selection": row["METABRIC_outcome_selection"], "gene_ids": {member["entrez_id"] for member in by_group[name] if member["in_ranking_universe"]}, "memberships": by_group[name]})
    for row in tables["repository_control_readiness_v1.csv"]:
        name = row["Membership entity ID"]
        references.append({"group_id": name, "name": row["Nombre exacto"], "reference_type": "Auxiliary control", "readiness_status": row["readiness_status"], "primary_blocker": "No blocker for the already permitted auxiliary control", "published_direction_rule": row["direction_rule"], "existing_score_available": True, "outcome_supervised_derivation": "Not a literature classifier", "source_metabric_outcome_selection": row["outcome_use_allowed_for_definition"], "gene_ids": {member["entrez_id"] for member in by_group[name] if member["in_ranking_universe"]}, "memberships": by_group[name]})
    require(len(references) == 27, "Previous reference registry changed")
    return references, members


def merge_previous_references(groups: list[dict], references: list[dict]) -> list[dict]:
    reviewed = {record["group_id"]: record for record in groups}
    registry = []
    for record in groups:
        registry.append({"group_id": record["group_id"], "collection": record["collection"], "reviewed_catalogue_member": True, "previous_reference": False, "existing_score_available": False, "active_for_coverage": record["active_for_coverage"], "included_in_exploratory_programmes": record["included_in_exploratory_programmes"], "effective_gene_count": len(record["gene_ids"]), "readiness_status": record["mapping_review"], "new_score_authorized": False})
    lookup = {record["group_id"]: record for record in registry}
    for reference in references:
        name = reference["group_id"]
        if name in reviewed:
            require(reviewed[name]["gene_ids"] == reference["gene_ids"], "Same earlier group label has different effective members: " + name)
            if name == "SIG_KIM49":
                expected = {(member["published_direction"], member["entrez_id"]) for member in reference["memberships"] if member["in_ranking_universe"]}
                actual = {(part["arm"], identifier) for part in reviewed[name]["memberships"] for identifier in part["gene_ids"]}
                require(expected == actual, "Earlier signed Kim49 arms differ")
            lookup[name].update(previous_reference=True, existing_score_available=reference["existing_score_available"])
        else:
            registry.append({"group_id": name, "collection": "Earlier documentary signatures", "reviewed_catalogue_member": False, "previous_reference": True, "existing_score_available": reference["existing_score_available"], "active_for_coverage": False, "included_in_exploratory_programmes": False, "effective_gene_count": len(reference["gene_ids"]), "readiness_status": reference["readiness_status"], "new_score_authorized": False})
    require(len(registry) == len({record["group_id"] for record in registry}), "Unified group registry contains duplicate labels")
    require(sum(record["previous_reference"] for record in registry) == 27, "An earlier signature or control was lost")
    require(sum(record["existing_score_available"] for record in registry) == 10, "Earlier score availability changed")
    return registry


def reviewed_membership_rows(groups: list[dict]):
    for record in groups:
        for part in record["memberships"]:
            for identifier in part["gene_ids"]:
                yield {"group_id": record["group_id"], "arm": part["arm"], "entrez_id": identifier, "mapping_status": part["mapping_status"], "reviewed_catalogue_member": True, "active_for_coverage": record["active_for_coverage"], "new_score_authorized": False}


def combined_membership_rows(groups: list[dict], references: list[dict]):
    yield from reviewed_membership_rows(groups)
    existing = {record["group_id"] for record in groups}
    for record in references:
        if record["group_id"] not in existing:
            for member in record["memberships"]:
                if member["in_ranking_universe"]:
                    yield {"group_id": record["group_id"], "arm": member["published_direction"], "entrez_id": member["entrez_id"], "mapping_status": "PREVIOUS_DOCUMENTARY_REFERENCE_ONLY", "reviewed_catalogue_member": False, "active_for_coverage": False, "new_score_authorized": False}


def export_programmes(groups: list[dict], output: Path) -> dict:
    programmes = sorted((record for record in groups if record["included_in_exploratory_programmes"]), key=lambda record: record["programme_order"])
    aliases = defaultdict(list)
    for record in programmes:
        aliases[gene_set_sha256(record["gene_ids"])].append(record["group_id"])
    rows = []
    with (output / "programmes.gmt").open("w", encoding="utf-8", newline="") as handle:
        for record in programmes:
            digest = gene_set_sha256(record["gene_ids"])
            handle.write("\t".join([record["group_id"], record["source_reference"]] + sorted(record["gene_ids"], key=int)) + "\n")
            rows.append({"group_id": record["group_id"], "collection": record["collection"], "effective_gene_count": len(record["gene_ids"]), "membership_sha256": digest, "computational_profile": "sha256:" + digest, "exact_alias_count": len(aliases[digest]), "representative_group": min(aliases[digest]), "new_score_authorized": False})
    require(file_sha256(output / "programmes.gmt") == EXPECTED_PROGRAMME_GMT_SHA256, "The complete reviewed programme GMT differs from the fixed reference")
    write_csv(output / "programme_aliases.csv", rows, list(rows[0]))
    return {"programme_labels": len(rows), "computational_profiles": len(aliases), "exact_alias_excess": len(rows) - len(aliases)}


def catalogue_statistics(groups: list[dict], universe: set[str], output: Path) -> dict:
    active_groups = [record for record in groups if record["active_for_coverage"]]
    frequency = Counter(identifier for record in active_groups for identifier in record["gene_ids"])
    rows = [{"entrez_id": identifier, "active_group_count": frequency[identifier]} for identifier in sorted(universe, key=int)]
    write_csv(output / "gene_group_frequency.csv", rows, ["entrez_id", "active_group_count"])
    distribution = Counter(row["active_group_count"] for row in rows)
    write_csv(output / "membership_frequency_distribution.csv", [{"active_group_count": value, "gene_count": distribution[value]} for value in range(max(distribution) + 1)], ["active_group_count", "gene_count"])
    collections = defaultdict(list)
    for record in groups:
        collections[record["collection"]].append(record)
    collection_rows = []
    for name, records in sorted(collections.items()):
        genes = set().union(*(record["gene_ids"] for record in records))
        collection_rows.append({"collection": name, "group_count": len(records), "distinct_genes": len(genes), "membership_rows": sum(len(part["gene_ids"]) for record in records for part in record["memberships"]), "coverage_percent_descriptive_only": 100 * len(genes) / len(universe)})
    write_csv(output / "collection_coverage.csv", collection_rows, list(collection_rows[0]))
    mapped = [record for record in active_groups if record["gene_ids"]]
    smallest = min(len(record["gene_ids"]) for record in mapped)
    largest = max(len(record["gene_ids"]) for record in mapped)
    maximum_frequency = max(frequency.values())
    return {"reviewed_groups": len(groups), "reviewed_membership_rows": sum(len(part["gene_ids"]) for record in groups for part in record["memberships"]), "ranking_universe_genes": len(universe), "covered_genes_in_active_reviewed_groups": len(frequency), "uncovered_genes": len(universe) - len(frequency), "coverage_percent_descriptive_only": 100 * len(frequency) / len(universe), "smallest_nonempty_group_size": smallest, "smallest_groups": [record["group_id"] for record in mapped if len(record["gene_ids"]) == smallest], "largest_group_size": largest, "largest_groups": [record["group_id"] for record in mapped if len(record["gene_ids"]) == largest], "maximum_gene_group_frequency": maximum_frequency, "most_frequent_genes": sorted([identifier for identifier, count in frequency.items() if count == maximum_frequency], key=int)}


def preserve_input_hashes(hashes: dict[str, str]) -> None:
    for name, digest in hashes.items():
        require(file_sha256(Path(name)) == digest, "An inspected previous-step input changed: " + name)


def project_directory(script: Path) -> Path:
    script_directory = script.resolve(strict=True).parent
    for directory in (script_directory,) + tuple(script_directory.parents[:4]):
        if directory == Path.home() or directory == Path(directory.anchor):
            break
        if (directory / ".git").exists() or (directory / "pyproject.toml").is_file():
            return directory
    return script_directory


def discover_previous_directories(project: Path, find_transcriptomics: bool, find_signature_scores: bool) -> dict[str, Path]:
    project = project.resolve(strict=True)
    candidates = {"transcriptomics_dir": [], "signature_scores_dir": []}
    pending = [(project, 0)]
    directories_seen = 0
    entries_seen = 0
    while pending:
        directory, depth = pending.pop()
        directories_seen += 1
        require(directories_seen <= DISCOVERY_MAX_DIRECTORIES, "Automatic discovery directory limit reached; place previous outputs in a smaller project or use explicit path options")
        files = set()
        children = []
        with os.scandir(directory) as entries:
            for entry in entries:
                entries_seen += 1
                require(entries_seen <= DISCOVERY_MAX_ENTRIES, "Automatic discovery entry limit reached; place previous outputs in a smaller project or use explicit path options")
                if entry.is_symlink():
                    continue
                if entry.is_file(follow_symlinks=False):
                    files.add(entry.name)
                elif entry.is_dir(follow_symlinks=False) and entry.name not in DISCOVERY_SKIPPED_DIRECTORIES and not entry.name.startswith("."):
                    children.append(Path(entry.path))
        if find_transcriptomics and {"metabric_gene_annotation.csv", "metabric_transcriptomics_summary.csv"} <= files:
            candidates["transcriptomics_dir"].append(directory)
        if find_signature_scores and "RUN_STATE.json" in files:
            manifest_path = directory / "results/manifest_v1.json"
            definitions = directory / "definitions"
            results = directory / "results"
            if not definitions.is_symlink() and definitions.is_dir() and not results.is_symlink() and results.is_dir() and not manifest_path.is_symlink() and manifest_path.is_file():
                require(manifest_path.stat().st_size <= DISCOVERY_MAX_MANIFEST_BYTES, "Candidate previous-step manifest exceeds the fixed discovery limit: " + str(manifest_path))
                manifest = read_json(manifest_path)
                if manifest.get("version") == EXPECTED_PREVIOUS_VERSION:
                    candidates["signature_scores_dir"].append(directory)
        if depth < DISCOVERY_MAX_DEPTH:
            pending.extend((child, depth + 1) for child in sorted(children, reverse=True))
    selected = {}
    for key, required in (("transcriptomics_dir", find_transcriptomics), ("signature_scores_dir", find_signature_scores)):
        if not required:
            continue
        label = "step03 gene annotation and summary" if key == "transcriptomics_dir" else "step04 completion metadata and definitions"
        matches = sorted(candidates[key])
        require(matches, "Cannot find " + label + " within " + str(project) + "; complete the previous step in this project before running05")
        require(len(matches) == 1, "Ambiguous previous outputs for " + label + ": " + "; ".join(str(path) for path in matches) + ". Keep one intended input per step in this project or use the optional explicit path arguments")
        selected[key] = matches[0]
    return selected


def automatic_output_directory(project: Path) -> Path:
    base = project / "modeling_data/gene_set_catalogue_v1"
    if not base.exists() and not base.is_symlink() and not base.with_name(base.name + ".zip").exists():
        return base
    dated = base.with_name(base.name + "_" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S_%fZ"))
    require(not dated.exists() and not dated.is_symlink() and not dated.with_name(dated.name + ".zip").exists(), "Automatic dated output already exists")
    return dated


def resolve_workflow_paths(args: argparse.Namespace, script: Path) -> argparse.Namespace:
    project = project_directory(script)
    automatic = []
    if args.transcriptomics_dir is None or args.signature_scores_dir is None:
        discovered = discover_previous_directories(project, args.transcriptomics_dir is None, args.signature_scores_dir is None)
        for name, path in discovered.items():
            setattr(args, name, path)
            automatic.append(name)
    if args.output_dir is None:
        args.output_dir = automatic_output_directory(project)
        automatic.append("output_dir")
    args.workflow_paths = {"project_root": str(project), "transcriptomics_dir": str(args.transcriptomics_dir.resolve()), "signature_scores_dir": str(args.signature_scores_dir.resolve()), "output_dir": str(args.output_dir.resolve()), "automatically_resolved": automatic, "discovery_max_directory_depth": DISCOVERY_MAX_DEPTH}
    return args


def reserve_output(path: Path, input_roots: list[Path]) -> Path:
    require(not path.exists() and not path.is_symlink(), "Output must be a NEW directory; overwrite is not supported")
    output = path.resolve()
    for root in input_roots:
        root = root.resolve()
        require(output != root and root not in output.parents and output not in root.parents, "Output must be separate from previous-step inputs")
    for ancestor in (output,) + tuple(output.parents):
        require(not (ancestor / "FREEZE_RECORD.json").exists(), "Refusing to write inside a frozen phase")
    output.mkdir(parents=True, exist_ok=False)
    return output


def output_manifest(output: Path) -> dict:
    files = {}
    for path in sorted(output.rglob("*")):
        require(not path.is_symlink(), "Unexpected symbolic output")
        if path.is_file() and path.name != "manifest.json":
            files[path.relative_to(output).as_posix()] = {"sha256": file_sha256(path), "size_bytes": path.stat().st_size}
    return files


def export_zip(output: Path) -> Path:
    manifest = read_json(output / "manifest.json")
    require(output_manifest(output) == manifest["files"], "Output files changed after manifest creation")
    destination = output.with_name(output.name + ".zip")
    temporary = destination.with_name(destination.name + ".partial")
    require(not destination.exists() and not temporary.exists(), "Output ZIP already exists")
    with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
        for name in sorted(manifest["files"]):
            archive.write(output / name, "gene_set_catalogue/" + name)
        archive.write(output / "manifest.json", "gene_set_catalogue/manifest.json")
    with zipfile.ZipFile(temporary) as archive:
        require(archive.testzip() is None, "Return ZIP CRC failure")
        require(set(archive.namelist()) == {"gene_set_catalogue/" + name for name in manifest["files"]} | {"gene_set_catalogue/manifest.json"}, "Return ZIP inventory differs")
        for name, expected in manifest["files"].items():
            with archive.open("gene_set_catalogue/" + name) as handle:
                digest = hashlib.sha256()
                count = 0
                for block in iter(lambda: handle.read(4 * 1024 * 1024), b""):
                    digest.update(block)
                    count += len(block)
            require(count == expected["size_bytes"] and digest.hexdigest() == expected["sha256"], "Return ZIP member differs")
    os.replace(temporary, destination)
    return destination


def execute(args: argparse.Namespace, output: Path) -> dict:
    previous = read_previous_outputs(args.transcriptomics_dir, args.signature_scores_dir)
    groups = load_reviewed_groups(previous["universe"])
    references, previous_memberships = previous_reference_records(previous)
    registry = merge_previous_references(groups, references)
    results = output / "results"
    results.mkdir()
    metadata_fields = [field for field in groups[0] if field not in {"memberships", "gene_ids"}]
    write_csv(results / "reviewed_gene_set_catalogue.csv", ({field: record[field] for field in metadata_fields} for record in groups), metadata_fields)
    write_csv(results / "gene_set_catalogue.csv", registry, list(registry[0]))
    membership_fields = ["group_id", "arm", "entrez_id", "mapping_status", "reviewed_catalogue_member", "active_for_coverage", "new_score_authorized"]
    write_compressed_csv(results / "reviewed_gene_set_memberships.csv.gz", reviewed_membership_rows(groups), membership_fields)
    write_compressed_csv(results / "gene_set_memberships.csv.gz", combined_membership_rows(groups, references), membership_fields)
    reference_fields = [field for field in references[0] if field not in {"gene_ids", "memberships"}]
    write_csv(results / "previous_signature_catalogue.csv", ({field: record[field] for field in reference_fields} for record in references), reference_fields)
    write_csv(results / "previous_signature_memberships.csv", previous_memberships, list(previous_memberships[0]))
    programmes = export_programmes(groups, results)
    statistics = catalogue_statistics(groups, previous["universe"], results)
    deferred = json.loads(DEFERRED_GROUPS)
    require(len(deferred) == 34 and Counter(row["review_status"] for row in deferred) == {"UNRESOLVED_IDENTITY": 30, "EXCLUDED_BY_REGISTERED_SIZE_LIMIT": 4}, "Deferred group reviews changed")
    require(not {row["group_id"] for row in deferred} & {record["group_id"] for record in groups}, "A deferred group was silently admitted")
    write_csv(results / "deferred_group_reviews.csv", deferred, list(deferred[0]))
    review_rows = []
    for record in groups:
        if record["unresolved_source_rows"] or (record["accepted_source_rows"] and record["source_rows_in_universe"] is not None and record["source_rows_in_universe"] / record["accepted_source_rows"] < 0.5):
            review_rows.append({"group_id": record["group_id"], "published_source_rows": record["published_source_rows"], "accepted_source_rows": record["accepted_source_rows"], "source_rows_in_universe": record["source_rows_in_universe"], "unresolved_source_rows": record["unresolved_source_rows"], "resolved_outside_universe_rows": record["resolved_outside_universe_rows"], "mapping_review": record["mapping_review"], "automatically_excluded_by_this_review_table": False})
    write_csv(results / "mapping_review_queue.csv", review_rows, list(review_rows[0]))
    write_json(results / "source_attributions.json", SOURCE_ATTRIBUTIONS)
    write_json(results / "preserved_restrictions.json", PRESERVED_RESTRICTIONS)
    for name in ("metabric_rank_universe_v1_entrez.txt",):
        (results / name).write_text("\n".join(sorted(previous["universe"], key=int)) + "\n", encoding="utf-8")
        require(file_sha256(results / name) == RANK_UNIVERSE_SHA256, "Output gene universe differs")
    preserve_input_hashes(previous["input_hashes"])
    summary = {"version": VERSION, "status": "PASS_REVIEWED_GENE_GROUPS_CONSOLIDATED", "scope": SCOPE, "statistics": dict(statistics, **programmes), "unified_registry_labels": len(registry), "previous_signature_and_control_references": len(references), "previous_references_already_in_reviewed_catalogue": sum(record["reviewed_catalogue_member"] and record["previous_reference"] for record in registry), "previous_reference_labels_retained_as_documentary_only": sum(not record["reviewed_catalogue_member"] for record in registry), "earlier_existing_score_entities": sorted(previous["existing_score_entities"]), "earlier_score_equivalence_declaration": previous["previous_score_equivalence_declaration"], "earlier_patient_scores_rechecked": False, "earlier_clinical_models_rechecked": False, "upstream_evidence_is_synthetic_fixture": previous["upstream_evidence_is_synthetic_fixture"], "previous_input_files_sha256_before_and_after": previous["input_hashes"], "embedded_definition_sha256": EMBEDDED_DEFINITION_SHA256, "reviewed_membership_relation_sha256": REVIEWED_MEMBERSHIP_RELATION_SHA256, "reviewed_snapshot_provenance": REVIEWED_SNAPSHOT_PROVENANCE, "source_patient_data_embedded": False, "new_run_frozen": False, "native_validation_inherited": False, "script_sha256": file_sha256(Path(__file__).resolve()), "software": {"python": sys.version, "platform": platform.platform(), "third_party_dependencies": []}}
    summary["workflow_paths"] = args.workflow_paths
    write_json(results / "catalogue_summary.json", summary)
    return summary


def cli() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Integrate the full reviewed gene-set library with the outputs of thesis steps03 and04")
    parser.add_argument("--transcriptomics-dir", type=Path, help="Optional override for the automatically located step03 output")
    parser.add_argument("--signature-scores-dir", type=Path, help="Optional override for the automatically located step04 output")
    parser.add_argument("--output-dir", type=Path, help="Optional override for the automatic project-relative output directory")
    parser.add_argument("--export-zip", action="store_true", help="Create one verified ZIP of the generated files")
    parser.add_argument("--self-test", action="store_true", help="Check embedded memberships and synthetic contract failures without reading previous outputs")
    parser.add_argument("--list-collections", action="store_true", help="List the included biological collections without reading previous outputs")
    parser.add_argument("--version", action="version", version=VERSION)
    args = parser.parse_args()
    if args.self_test or args.list_collections:
        if any([args.transcriptomics_dir, args.signature_scores_dir, args.output_dir, args.export_zip]) or (args.self_test and args.list_collections):
            parser.error("Select a single inspection mode without input/output arguments")
    return args


def main() -> int:
    args = cli()
    if args.self_test:
        return run_self_tests()
    if args.list_collections:
        groups = load_reviewed_groups(set(REVIEWED_RANK_UNIVERSE.splitlines()))
        for name, count in sorted(Counter(record["collection"] for record in groups).items()):
            print(str(count) + "\t" + name)
        return 0
    output = None
    try:
        args = resolve_workflow_paths(args, Path(__file__))
        print("[INPUT] Step03: " + str(args.transcriptomics_dir.resolve()), flush=True)
        print("[INPUT] Step04: " + str(args.signature_scores_dir.resolve()), flush=True)
        print("[OUTPUT] " + str(args.output_dir.resolve()), flush=True)
        output = reserve_output(args.output_dir, [args.transcriptomics_dir, args.signature_scores_dir])
        write_json(output / "RUN_STATE.json", {"version": VERSION, "status": "RUNNING", "started_utc": datetime.now(timezone.utc).isoformat()})
        summary = execute(args, output)
        state = {"version": VERSION, "status": "COMPLETED_NOT_FROZEN", "validation_status": summary["status"], "completed_at_utc": datetime.now(timezone.utc).isoformat(), "new_scores_or_models_or_outcome_associations": False}
        write_json(output / "RUN_STATE.json", state)
        print("[OK] All reviewed gene sets and previous signature references consolidated")
        print("[OK] Reviewed groups: " + str(summary["statistics"]["reviewed_groups"]) + "; memberships: " + str(summary["statistics"]["reviewed_membership_rows"]))
        print("[OK] Previous reference labels retained; existing scores, panel and statistical plan unchanged")
    except Exception as error:
        if output is None:
            print("[ERROR] " + str(error), file=sys.stderr)
            return 21
        (output / "failure.txt").write_text(traceback.format_exc(), encoding="utf-8")
        state = {"version": VERSION, "status": "FAILED", "error": str(error), "new_scores_or_models_or_outcome_associations": False}
        write_json(output / "RUN_STATE.json", state)
        print("[ERROR] " + str(error), file=sys.stderr)
    write_json(output / "manifest.json", {"version": VERSION, "status": state["status"], "files": output_manifest(output)})
    if args.export_zip:
        archive = export_zip(output)
        print("ARCHIVO_UNICO_PARA_DEVOLVER=" + str(archive))
        print("SHA256_ARCHIVO_UNICO=" + file_sha256(archive))
    return 0 if state["status"] == "COMPLETED_NOT_FROZEN" else 21


class ReviewedLibraryTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.universe = set(REVIEWED_RANK_UNIVERSE.splitlines())
        cls.groups = load_reviewed_groups(cls.universe)
        cls.lookup = {record["group_id"]: record for record in cls.groups}

    def test_complete_reviewed_group_inventory(self):
        self.assertEqual(len(self.groups), 15920)
        self.assertEqual(sum(len(part["gene_ids"]) for record in self.groups for part in record["memberships"]), 2011555)

    def test_complete_hallmark_collection(self):
        self.assertEqual(sum(record["collection"] == "Hallmark" for record in self.groups), 50)

    def test_descriptive_collections_cover_required_programmes(self):
        names = {record["collection"] for record in self.groups}
        for name in ["Reactome", "Gene Ontology Biological Process", "WikiPathways", "Transcription factor targets from GTRD", "Transcription factor motif targets", "Cancer cell programmes", "Cell type and cell state markers", "Chemical and genetic perturbation signatures", "Immunological signatures"]:
            self.assertIn(name, names)

    def test_active_coverage_is_preserved(self):
        active = set().union(*(record["gene_ids"] for record in self.groups if record["active_for_coverage"]))
        self.assertEqual(len(active), 19540)
        self.assertLessEqual(active, self.universe)

    def test_registered_programme_sizes_are_preserved(self):
        programmes = [record for record in self.groups if record["included_in_exploratory_programmes"]]
        self.assertEqual(len(programmes), 15793)
        self.assertTrue(all(15 <= len(record["gene_ids"]) <= 500 for record in programmes))

    def test_small_historical_controls_are_not_padded_or_removed(self):
        self.assertEqual(len(self.lookup["REP_FRIDMAN_SENESCENCE_DN"]["gene_ids"]), 12)
        self.assertEqual(len(self.lookup["REP_HASINA_NOL7_TARGETS_DN"]["gene_ids"]), 13)
        self.assertFalse(self.lookup["REP_FRIDMAN_SENESCENCE_DN"]["included_in_exploratory_programmes"])

    def test_signed_kim_arms_remain_separate(self):
        arms = {part["arm"]: len(part["gene_ids"]) for part in self.lookup["SIG_KIM49"]["memberships"]}
        self.assertEqual(arms, {"UP": 22, "DOWN": 27})

    def test_separate_up_down_control_labels_are_retained(self):
        self.assertIn("REP_HASINA_NOL7_TARGETS_UP", self.lookup)
        self.assertIn("REP_HASINA_NOL7_TARGETS_DN", self.lookup)
        self.assertNotEqual(self.lookup["REP_HASINA_NOL7_TARGETS_UP"]["gene_ids"], self.lookup["REP_HASINA_NOL7_TARGETS_DN"]["gene_ids"])

    def test_data8_effective_members_and_unresolved_rows_are_distinct(self):
        record = next(record for record in self.groups if record["group_id"].startswith("MICHELATTI2024_DATA8_"))
        self.assertEqual(len(record["gene_ids"]), 549)
        self.assertEqual(record["unresolved_source_rows"], 18)
        self.assertEqual(record["resolved_outside_universe_rows"], 101)
        self.assertTrue(record["published_list_enumeration_complete"])
        self.assertFalse(record["included_in_exploratory_programmes"])

    def test_septin4_reviewed_membership_is_preserved(self):
        record = self.lookup["HANGAUER_BT474_PERSISTER_UP_Q005_FC2_FPKM1_ADAPTATION"]
        self.assertEqual(len(record["gene_ids"]), 773)
        self.assertIn("5414", record["gene_ids"])
        self.assertFalse(record["new_score_authorized"])

    def test_curated_lists_need_not_add_new_genes(self):
        self.assertTrue(any(record["collection"] == "Curated experimental signatures" for record in self.groups))
        self.assertTrue(any(record["collection"] == "Lobular carcinoma and fibroblast context" for record in self.groups))

    def test_notch2_pathways_do_not_replace_deferred_experimental_signature(self):
        self.assertIn("REACTOME_SIGNALING_BY_NOTCH2", self.lookup)
        self.assertEqual(PRESERVED_RESTRICTIONS["experimental_notch2_signature"], "DEFERRED_SOURCE_PROVENANCE_REMAINS_UNRESOLVED")

    def test_ren15_exclusion_is_preserved(self):
        self.assertEqual(PRESERVED_RESTRICTIONS["ren15"], "TECHNICAL_EXCLUSION_RETAINED")
        self.assertNotIn("SIG_REN15", self.lookup)

    def test_exact_aliases_preserve_all_labels(self):
        programmes = [record for record in self.groups if record["included_in_exploratory_programmes"]]
        profiles = {gene_set_sha256(record["gene_ids"]) for record in programmes}
        self.assertEqual(len(profiles), 15784)
        self.assertEqual(len(programmes) - len(profiles), 9)

    def test_source_metabric_use_and_outcome_derivation_have_separate_fields(self):
        for record in self.groups:
            self.assertIn("source_metabric_use_review", record)
            self.assertIn("source_outcome_derivation_review", record)

    def test_group_membership_does_not_authorize_scoring(self):
        self.assertTrue(all(record["new_score_authorized"] is False for record in self.groups))

    def test_deferred_groups_stay_outside_reviewed_definitions(self):
        deferred = json.loads(DEFERRED_GROUPS)
        self.assertEqual(Counter(record["review_status"] for record in deferred), {"UNRESOLVED_IDENTITY": 30, "EXCLUDED_BY_REGISTERED_SIZE_LIMIT": 4})
        self.assertFalse({record["group_id"] for record in deferred} & set(self.lookup))
        self.assertTrue(all(record["new_membership_authorized"] is False for record in deferred))

    def test_candidate_gene_ids_are_not_admitted_by_name(self):
        deferred = json.loads(DEFERRED_GROUPS)
        self.assertTrue(any(record["candidate_gene_id_not_admitted"] for record in deferred))
        self.assertTrue(all(record["new_membership_authorized"] is False for record in deferred))

    def test_gmt_reproduces_the_complete_reviewed_programme_file(self):
        with tempfile.TemporaryDirectory() as directory:
            result = export_programmes(self.groups, Path(directory))
            self.assertEqual(result["programme_labels"], 15793)
            self.assertEqual(file_sha256(Path(directory) / "programmes.gmt"), EXPECTED_PROGRAMME_GMT_SHA256)

    def test_same_label_with_changed_previous_members_cannot_merge(self):
        references = [{"group_id": "SIG_KIM49", "gene_ids": {"1"}, "memberships": [], "existing_score_available": True}]
        with self.assertRaises(ValueError):
            merge_previous_references(self.groups, references)


class ContractFailureTests(unittest.TestCase):
    def test_noncanonical_gene_ids_are_not_currentized(self):
        for value in ("01", "1.0", " 1", "+1", "0", "-1", "GENE"):
            with self.subTest(value=value), self.assertRaises(ValueError):
                gene_id(value)

    def test_gene_membership_digest_depends_on_identity_not_order(self):
        self.assertEqual(gene_set_sha256({"10", "2"}), text_sha256("2\n10\n"))
        self.assertNotEqual(gene_set_sha256({"1", "2"}), gene_set_sha256({"1", "3"}))

    def test_changed_embedded_member_cannot_borrow_the_original_hash(self):
        altered = REVIEWED_GROUP_MEMBERSHIPS.replace("\t", " ", 1)
        with patch.dict(globals(), REVIEWED_GROUP_MEMBERSHIPS=altered), self.assertRaises(ValueError):
            verify_embedded_definitions()

    def test_changed_metadata_cannot_borrow_the_original_hash(self):
        with patch.dict(globals(), REVIEWED_GROUP_METADATA=REVIEWED_GROUP_METADATA + " "), self.assertRaises(ValueError):
            verify_embedded_definitions()

    def test_wrong_ranking_universe_is_rejected(self):
        self.assertEqual(text_sha256(REVIEWED_RANK_UNIVERSE), RANK_UNIVERSE_SHA256)
        self.assertNotEqual(text_sha256(REVIEWED_RANK_UNIVERSE + "1\n"), RANK_UNIVERSE_SHA256)

    def test_runtime_checks_remain_active_under_optimized_python(self):
        with self.assertRaises(ValueError):
            require(False, "must remain blocked")

    def test_existing_output_is_never_overwritten(self):
        with tempfile.TemporaryDirectory() as directory:
            with self.assertRaises(ValueError):
                reserve_output(Path(directory), [])

    def test_output_inside_a_previous_step_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            previous = Path(directory) / "previous"
            previous.mkdir()
            with self.assertRaises(ValueError):
                reserve_output(previous / "catalogue", [previous])

    def test_output_inside_a_frozen_phase_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / "FREEZE_RECORD.json").write_text("{}")
            with self.assertRaises(ValueError):
                reserve_output(root / "new", [])

    def test_changed_previous_input_is_not_relabelled(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "definition.txt"
            path.write_text("original")
            digest = file_sha256(path)
            path.write_text("changed")
            with self.assertRaises(ValueError):
                preserve_input_hashes({str(path): digest})

    def test_missing_or_traversing_previous_input_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            for name in ("missing.csv", "../outside.csv"):
                with self.assertRaises(ValueError):
                    safe_input(Path(directory), name)

    def test_symbolic_previous_input_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / "original.txt").write_text("data")
            (root / "link.txt").symlink_to(root / "original.txt")
            with self.assertRaises(ValueError):
                safe_input(root, "link.txt")

    def test_definition_file_hash_cannot_be_replaced_by_observation(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "definitions.csv"
            path.write_text("id\nchanged\n")
            with self.assertRaises(ValueError):
                read_csv(path, text_sha256("id\noriginal\n"))

    def test_changed_return_members_do_not_pass_with_a_success_label(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "result"
            output.mkdir()
            write_json(output / "RUN_STATE.json", {"status": "COMPLETED_NOT_FROZEN"})
            write_json(output / "manifest.json", {"files": output_manifest(output)})
            (output / "RUN_STATE.json").write_text('{"status":"FORGED"}')
            with self.assertRaises(ValueError):
                export_zip(output)

    def test_return_zip_is_created_only_after_member_verification(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "result"
            output.mkdir()
            write_json(output / "RUN_STATE.json", {"status": "FAILED"})
            write_json(output / "manifest.json", {"files": output_manifest(output)})
            archive_path = export_zip(output)
            self.assertTrue(archive_path.is_file())
            self.assertFalse(archive_path.with_name(archive_path.name + ".partial").exists())
            with zipfile.ZipFile(archive_path) as archive:
                self.assertIsNone(archive.testzip())
                self.assertEqual(json.loads(archive.read("gene_set_catalogue/RUN_STATE.json"))["status"], "FAILED")

    def test_boolean_and_count_fields_are_strict(self):
        with self.assertRaises(ValueError):
            parse_boolean("yes", "permission")
        with self.assertRaises(ValueError):
            parse_optional_integer("1.0", "size")

    def test_no_pipeline_permission_is_opened(self):
        for key, value in SCOPE.items():
            if key != "operation":
                self.assertIs(value, False, key)


class AutomaticPathTests(unittest.TestCase):
    def make_project(self, root: Path) -> tuple[Path, Path, Path]:
        script = root / "05_build_metabric_gene_set_catalogue.py"
        script.write_text("workflow entry point", encoding="utf-8")
        transcriptomics = root / "outputs/genes_from_previous_step"
        scores = root / "outputs/earlier_signature_run"
        transcriptomics.mkdir(parents=True)
        (transcriptomics / "metabric_gene_annotation.csv").write_text("literal gene metadata", encoding="utf-8")
        (transcriptomics / "metabric_transcriptomics_summary.csv").write_text("literal aggregate metadata", encoding="utf-8")
        (scores / "definitions").mkdir(parents=True)
        (scores / "results").mkdir()
        write_json(scores / "RUN_STATE.json", {"status": "COMPLETED_NOT_FROZEN"})
        write_json(scores / "results/manifest_v1.json", {"version": EXPECTED_PREVIOUS_VERSION})
        return script, transcriptomics, scores

    def empty_arguments(self) -> argparse.Namespace:
        return argparse.Namespace(transcriptomics_dir=None, signature_scores_dir=None, output_dir=None)

    def test_normal_command_accepts_no_path_arguments(self):
        with patch.object(sys, "argv", ["05_build_metabric_gene_set_catalogue.py"]):
            args = cli()
        self.assertIsNone(args.transcriptomics_dir)
        self.assertIsNone(args.signature_scores_dir)
        self.assertIsNone(args.output_dir)

    def test_arbitrary_previous_directory_names_are_recognized(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            args = resolve_workflow_paths(self.empty_arguments(), script)
            self.assertEqual(args.transcriptomics_dir, genes)
            self.assertEqual(args.signature_scores_dir, scores)
            self.assertEqual(args.output_dir, root / "modeling_data/gene_set_catalogue_v1")
            self.assertEqual(len(args.workflow_paths["automatically_resolved"]), 3)
            self.assertFalse(args.output_dir.exists())

    def test_script_in_scripts_directory_finds_the_git_project_root(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            (root / ".git").mkdir()
            (root / "scripts").mkdir()
            relocated = root / "scripts" / script.name
            script.rename(relocated)
            args = resolve_workflow_paths(self.empty_arguments(), relocated)
            self.assertEqual(args.workflow_paths["project_root"], str(root))
            self.assertEqual(args.transcriptomics_dir, genes)
            self.assertEqual(args.signature_scores_dir, scores)

    def test_project_resolution_is_independent_of_working_directory(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            with patch.object(Path, "cwd", return_value=root / "unrelated"):
                args = resolve_workflow_paths(self.empty_arguments(), script)
            self.assertEqual(args.transcriptomics_dir, genes)
            self.assertEqual(args.signature_scores_dir, scores)

    def test_duplicate_gene_annotations_are_ambiguous(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            shutil.copytree(genes, root / "another_gene_run")
            with self.assertRaisesRegex(ValueError, "Ambiguous previous outputs"):
                resolve_workflow_paths(self.empty_arguments(), script)

    def test_incomplete_score_copy_is_not_silently_ignored(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            duplicate = root / "another_score_run"
            shutil.copytree(scores, duplicate)
            write_json(duplicate / "RUN_STATE.json", {"status": "RUNNING"})
            with self.assertRaisesRegex(ValueError, "Ambiguous previous outputs"):
                resolve_workflow_paths(self.empty_arguments(), script)

    def test_missing_previous_step_does_not_create_outputs(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            shutil.rmtree(scores)
            with self.assertRaisesRegex(ValueError, "Cannot find"):
                resolve_workflow_paths(self.empty_arguments(), script)
            self.assertFalse((root / "modeling_data").exists())

    def test_environment_copies_are_excluded_from_discovery(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            shutil.copytree(genes, root / ".venv/example")
            shutil.copytree(scores, root / "node_modules/example")
            args = resolve_workflow_paths(self.empty_arguments(), script)
            self.assertEqual(args.transcriptomics_dir, genes)
            self.assertEqual(args.signature_scores_dir, scores)

    def test_discovery_never_follows_a_symbolic_directory(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            (root / "linked_previous_output").symlink_to(scores, target_is_directory=True)
            args = resolve_workflow_paths(self.empty_arguments(), script)
            self.assertEqual(args.signature_scores_dir, scores)

    def test_existing_default_output_is_retained_and_new_path_selected(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            previous = root / "modeling_data/gene_set_catalogue_v1"
            previous.mkdir(parents=True)
            (previous / "sentinel.txt").write_text("retain", encoding="utf-8")
            chosen = automatic_output_directory(root)
            self.assertNotEqual(chosen, previous)
            self.assertEqual(chosen.parent, previous.parent)
            self.assertTrue(chosen.name.startswith(previous.name + "_"))
            self.assertFalse(chosen.exists())
            self.assertEqual((previous / "sentinel.txt").read_text(), "retain")

    def test_explicit_input_can_resolve_only_its_own_ambiguity(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            shutil.copytree(scores, root / "another_score_run")
            args = self.empty_arguments()
            args.signature_scores_dir = scores
            args = resolve_workflow_paths(args, script)
            self.assertEqual(args.transcriptomics_dir, genes)
            self.assertEqual(args.signature_scores_dir, scores)
            self.assertNotIn("signature_scores_dir", args.workflow_paths["automatically_resolved"])

    def test_directory_budget_is_not_automatically_expanded(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            with patch.dict(globals(), DISCOVERY_MAX_DIRECTORIES=1), self.assertRaisesRegex(ValueError, "directory limit"):
                resolve_workflow_paths(self.empty_arguments(), script)

    def test_discovery_does_not_read_expression_scores_or_clinical_tables(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            script, genes, scores = self.make_project(root)
            for path in (genes / "metabric_expression_entrez_median.csv.gz", scores / "results/patient_scores.csv", root / "clinical.csv"):
                path.write_bytes(b"must not be read")
            original_read_text = Path.read_text
            allowed = scores / "results/manifest_v1.json"
            def guarded_read(path, *args, **kwargs):
                self.assertEqual(path, allowed)
                return original_read_text(path, *args, **kwargs)
            with patch.object(Path, "read_text", guarded_read):
                args = resolve_workflow_paths(self.empty_arguments(), script)
            self.assertEqual(args.signature_scores_dir, scores)


def run_self_tests() -> int:
    verify_embedded_definitions()
    suite = unittest.TestSuite()
    for test in (ReviewedLibraryTests, ContractFailureTests, AutomaticPathTests):
        suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(test))
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    if result.wasSuccessful():
        print("SELF_TEST=PASS; CHECKS=" + str(result.testsRun))
        print("All embedded reviewed groups checked; no previous-step or patient files were read.")
        return 0
    return 21


